 3 | namespace App\Services;
 4 | 
 5 | /**
 6 |  * Zoom virtual-interview link generator.
 7 |  *
 8 |  * Self-contained MOCK provider (no external API keys needed): generates a
 9 |  * deterministic Zoom-style meeting (meeting ID + join link + continue/rejoin
10 |  * link + password) and stores it on the interview row. The applicant receives
11 |  * both links + password + interviewer name by email.
12 |  *
13 |  * To swap in the real Zoom Server-to-Server OAuth API later, replace
14 |  * ::createForInterview() internals with a POST to
15 |  * https://api.zoom.us/v2/users/me/meetings (see ZOOM_* env vars below) and
16 |  * keep the same return shape — callers and emails stay unchanged.
17 |  *
18 |  * Env (future real provider):
19 |  *   ZOOM_PROVIDER=mock|api, ZOOM_ACCOUNT_ID, ZOOM_CLIENT_ID,
20 |  *   ZOOM_CLIENT_SECRET
21 |  */
22 | class ZoomMeetingService
23 | {
24 |     /**
25 |      * @return array{meeting_id:string,join_url:string,continue_url:string,password:string}
26 |      */
27 |     public static function createForInterview(
28 |         string $interviewCode,
29 |         string $applicantName,
30 |         ?string $interviewerName = null,
31 |         ?string $position = null,
32 |     ): array {
33 |         // Real-provider hook (not wired yet — falls through to mock).
34 |         // if (config('services.zoom.provider') === 'api') { ... }
35 | 
36 |         // Mock Zoom-style meeting ID: 3-4-4 digit groups like real Zoom IDs.
37 |         $digits = '';
38 |         for ($i = 0; $i < 11; $i++) {
39 |             $digits .= (string) random_int(0, 9);
40 |         }
41 |         // Ensure it starts non-zero like a real meeting ID.
42 |         if ($digits[0] === '0') {
43 |             $digits[0] = (string) random_int(1, 9);
44 |         }
45 |         $meetingId = substr($digits, 0, 3).' '.substr($digits, 3, 4).' '.substr($digits, 7, 4);
46 |         $meetingIdCompact = str_replace(' ', '', $meetingId);
47 | 
48 |         // 6-char alphanumeric password (Zoom style).
49 |         $alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789';
50 |         $password = '';
51 |         for ($i = 0; $i < 6; $i++) {
52 |             $password .= $alphabet[random_int(0, strlen($alphabet) - 1)];
53 |         }
54 | 
55 |         // Zoom join links carry an encrypted ?pwd= hash; emulate with url-safe base64.
56 |         $pwdHash = rtrim(strtr(base64_encode($interviewCode.':'.$password), '+/', '-_'), '=');
57 |         $joinUrl = "https://zoom.us/j/{$meetingIdCompact}?pwd={$pwdHash}";
58 |         // 2nd link: same meeting, flagged as continue/rejoin (used if dropped).
59 |         $continueUrl = "https://zoom.us/j/{$meetingIdCompact}?pwd={$pwdHash}&continue=1#rejoin";
60 | 
61 |         return [
62 |             'meeting_id'   => $meetingIdCompact,
63 |             'join_url'     => $joinUrl,
64 |             'continue_url' => $continueUrl,
65 |             'password'     => $password,
66 |         ];
67 |     }
68 | 
69 |     /**
70 |      * Fill Zoom columns on an interview model when it is Virtual and has none.
71 |      * Returns true when links were generated.
72 |      */
73 |     public static function ensureForModel(object $interview, ?string $position = null): bool
74 |     {
75 |         if (($interview->mode ?? null) !== 'Virtual') {
76 |             return false;
77 |         }
78 |         if (! empty($interview->zoom_join_url)) {
79 |             return false;
80 |         }
81 |         $applicantName = $interview->applicant?->name ?? 'Applicant';
82 |         $zoom = static::createForInterview(
83 |             (string) ($interview->interview_code ?? 'INT'),
84 |             $applicantName,
85 |             $interview->interviewer_name,
86 |             $position ?? $interview->applicant?->jobPost?->title,
87 |         );
88 |         $interview->zoom_meeting_id = $zoom['meeting_id'];
89 |         $interview->zoom_join_url = $zoom['join_url'];
90 |         $interview->zoom_continue_url = $zoom['continue_url'];
91 |         $interview->zoom_password = $zoom['password'];
92 | 
93 |         return true;
94 |     }
95 | }

