// NOTE: the "embedded" entry pulls its own React copy, which crashes on
// our React 19 app ("ReactCurrentOwner" undefined — SDK pins React 18).
// Workaround: load the SDK bundle inside an <iframe> whose document is
// plain HTML (no React) — then init/join the Component View in there.
// The popup stays in-system; only the video box is an iframe.
try {
  const root = rootRef.current;
  if (!root) return;
  const meetingNumber = sig.meeting_number;
  const doc = document.implementation.createHTMLDocument("zoom-embed");
  void doc;
  const frame = window.document.createElement("iframe");
  frame.title = "Zoom meeting";
  frame.allow = "camera; microphone; display-capture; autoplay; clipboard-write";
  frame.style.width = "100%";
  frame.style.minHeight = "420px";
  frame.style.border = "0";
  frame.style.background = "#000";
  root.replaceChildren(frame);
  const payload = encodeURIComponent(
    JSON.stringify({
      sdkKey: sig.sdk_key,
      signature: sig.signature,
      meetingNumber,
      password: sig.password ?? "",
      userName: sig.user_name || "HR Interviewer",
    }),
  );
  // Same-origin srcdoc would inherit our React realm; instead use a
  // blob URL (opaque origin realm) so the SDK's React copy boots clean.
  const html = `<!doctype html><html><head><meta charset="utf-8"><style>html,body{margin:0;height:100%;background:#000}#z{height:100vh}</style></head><body><div id="z"></div><scr` +
    `ipt src="${window.location.origin}/node_modules/@zoom/meetingsdk/dist/zoomus-websdk-embedded.umd.min.js"></scr` +
    `ipt><scr` +
    `ipt>(function(){var d=JSON.parse(decodeURIComponent("${payload}"));var NS=window.ZoomMtgEmbedded||window.ZoomMtg;if(!NS){parent.postMessage({zoomEmbedError:"SDK bundle missing createClient"}," * ");return;}var client=NS.createClient();client.init({zoomAppRoot:document.getElementById("z"),language:"en-US",patchJsMedia:true,leaveOnPageUnload:true}).then(function(){return client.join({sdkKey:d.sdkKey,signature:d.signature,meetingNumber:d.meetingNumber,password:d.password,userName:d.userName});}).then(function(){parent.postMessage({zoomEmbedJoined:true}," * ");}).catch(function(e){parent.postMessage({zoomEmbedError:String((e&&(e.reason||e.message))||e)}," * ");});window.addEventListener("beforeunload",function(){try{client.leaveMeeting();}catch(x){}});})();</scr` +
    `ipt></body></html>`;
  const blob = new Blob([html], { type: "text/html" });
  const url = URL.createObjectURL(blob);
  const joined = await new Promise<boolean>((resolve, reject) => {
    const onMsg = (ev: MessageEvent) => {
      const data = ev.data as { zoomEmbedJoined?: boolean; zoomEmbedError?: string };
      if (!data || typeof data !== "object") return;
      if (data.zoomEmbedJoined) {
        window.removeEventListener("message", onMsg);
        resolve(true);
      } else if (data.zoomEmbedError) {
        window.removeEventListener("message", onMsg);
        reject(new Error(data.zoomEmbedError));
      }
    };
    window.addEventListener("message", onMsg);
    frame.src = url;
    setTimeout(() => {
      window.removeEventListener("message", onMsg);
      reject(new Error("Timed out loading Zoom SDK bundle (check /node_modules is served)"));
    }, 30000);
  });
  void joined;
  joinedRef.current = true;
  // Track the frame so closeZoomRoom can unload it.
  clientRef.current = {
    leaveMeeting: async () => {
      try {
        frame.src = "about:blank";
      } catch {
        /* ignore */
      }
      URL.revokeObjectURL(url);
    },
  };

