/* Zoom embed page entry — plain TS, NO React imports on purpose.
 * Bundled by Vite when /zoom-embed.html loads, so the SDK ships inside the
 * app bundle (no separate UMD file to 404) and boots in a React-free
 * document (no ReactCurrentOwner clash with the host app's React 19).
 * Protocol: parent iframe host sends {type:"zoom-join",...} via postMessage
 * after receiving {zoomEmbedReady:true}; we reply {zoomEmbedJoined:true}
 * or {zoomEmbedError:string}. */

import ZoomMtgEmbedded from "@zoom/meetingsdk/embedded";

type JoinMsg = {
  type: "zoom-join";
  sdkKey: string;
  signature: string;
  meetingNumber: string;
  password?: string;
  userName?: string;
};

function fail(msg: string): void {
  const el = document.getElementById("zoom-err");
  if (el) {
    el.style.display = "block";
    el.textContent = msg;
  }
  parent.postMessage({ zoomEmbedError: msg }, window.location.origin);
}

function ready(): void {
  parent.postMessage({ zoomEmbedReady: true }, window.location.origin);
}

try {
  const client = ZoomMtgEmbedded.createClient();
  window.addEventListener("message", (ev: MessageEvent) => {
    if (ev.origin !== window.location.origin) return;
    const d = (ev.data ?? {}) as Partial<JoinMsg>;
    if (d.type !== "zoom-join") return;
    const root = document.getElementById("zoom-root");
    if (!root) {
      fail("Zoom embed page missing #zoom-root.");
      return;
    }
    void client
      .init({
        zoomAppRoot: root,
        language: "en-US",
        patchJsMedia: true,
        leaveOnPageUnload: true,
      })
      .then(() =>
        client.join({
          sdkKey: String(d.sdkKey ?? ""),
          signature: String(d.signature ?? ""),
          meetingNumber: String(d.meetingNumber ?? ""),
          password: String(d.password ?? ""),
          userName: String(d.userName ?? "HR Interviewer"),
        }),
      )
      .then(() => {
        parent.postMessage({ zoomEmbedJoined: true }, window.location.origin);
      })
      .catch((e: unknown) => {
        const r = e as { reason?: unknown; message?: unknown } | null;
        fail(`Zoom join failed: ${String(r?.reason ?? r?.message ?? e)}`);
      });
  });
  window.addEventListener("beforeunload", () => {
    try {
      void client.leaveMeeting();
    } catch {
      /* ignore */
    }
  });
  ready();
} catch (e) {
  const r = e as { message?: unknown } | null;
  fail(`Zoom embed failed to boot: ${String(r?.message ?? e)}`);
}

await new Promise<void>((resolve, reject) => {
  let settled = false;
  const timer = window.setTimeout(() => {
    if (settled) return;
    settled = true;
    window.removeEventListener("message", onMsg);
    reject(
      new Error(
        "Timed out loading Zoom embed page (/zoom-embed.html never signalled ready — hard-refresh, then open F12 Console for the [zoom-embed] error)",
      ),
    );
  }, 45000);
  const onMsg = (ev: MessageEvent) => {
    // Accept ready from the iframe even if origin differs (file:// edge).
    const data = ev.data as { zoomEmbedReady?: boolean; zoomEmbedJoined?: boolean; zoomEmbedError?: string };
    if (!data || typeof data !== "object") return;
    if (data.zoomEmbedReady) {
      try {
        // Post to the iframe's actual origin ("*" is safe here: the
        // payload is a single-use join signature for this meeting).
        frame.contentWindow?.postMessage(joinParams, "*");
      } catch (e) {
        if (!settled) {
          settled = true;
          window.clearTimeout(timer);
          window.removeEventListener("message", onMsg);
          reject(e instanceof Error ? e : new Error(String(e)));
        }
      }
    } else if (data.zoomEmbedJoined) {
      if (settled) return;
      settled = true;
      window.clearTimeout(timer);
      window.removeEventListener("message", onMsg);
      resolve();
    } else if (typeof data.zoomEmbedError === "string") {
      if (settled) return;
      settled = true;
      window.clearTimeout(timer);
      window.removeEventListener("message", onMsg);
      reject(new Error(data.zoomEmbedError));
    }
  };
  window.addEventListener("message", onMsg);
  // Same-origin iframe: relative URL keeps origin identical so the
  // embed page's origin check passes. Add a cache-buster so a stale
  // copy of zoom-embed.html (old UMD script tags) can't linger.
  frame.src = `/zoom-embed.html?t=${Date.now()}`;
});

